contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public function with parameters: caller address to attempt the call (simulated by using call from this contract
    // and an amount of ETH to send with the call to observe effects on balances).
    function run(address payable caller, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to forward");
        // record before-values
        address beforeOwner = c.smartfix_owner();
        uint256 beforeBalance = address(c).balance;

        // attempt call as if from this contract: if caller equals beforeOwner, we expect success only when the call originates from owner.
        // But since external calls originate from this contract, we simulate two cases by branching on equality.
        bool reverted;
        if (caller == beforeOwner) {
            // If caller equals owner, we expect the call to succeed when invoked (since msg.sender will be this contract, not caller).
            // To make a meaningful universal property: regardless of inputs, sudicideAnyone reverts unless the InvMutTest contract itself is the owner.
            // So we attempt the call and capture revert flag.
            try c.sudicideAnyone{value: sendAmount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // For non-owner, calling will also be from this contract, so behavior should be the same: capture revert flag.
            try c.sudicideAnyone{value: sendAmount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        address afterOwner = c.smartfix_owner();
        uint256 afterBalance = address(c).balance;

        // General rule: If the call did not revert then the caller (msg.sender of c) must have been the owner (i.e., this contract equals beforeOwner)
        // and the contract balance must have been sent to that owner (so address(c).balance decreased by at most sendAmount and owner may have been paid).
        // Because we cannot observe external account balances of owner, we assert that: (!reverted) implies (beforeOwner == address(this) && afterBalance <= beforeBalance).
        assert((!reverted) ? (beforeOwner == address(this) && afterBalance <= beforeBalance) : (afterOwner == beforeOwner && afterBalance == beforeBalance));
    }

    receive() external payable { }
}
